import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        if (s.length() < p.length()) return result;

        int[] pCount = new int[26];
        int[] windowCount = new int[26];

        for (char c : p.toCharArray()) {
            pCount[c - 'a']++;
        }

        int windowSize = p.length();

        for (int i = 0; i < s.length(); i++) {
            windowCount[s.charAt(i) - 'a']++;

            if (i >= windowSize) {
                windowCount[s.charAt(i - windowSize) - 'a']--;
            }

            if (Arrays.equals(pCount, windowCount)) {
                result.add(i - windowSize + 1);
            }
        }

        return result;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findAnagrams(String s, String p) {
        List<Integer> result = new ArrayList<>();
        if (s.length() < p.length()) return result;

        int[] pCount = new int[26];
        int[] sCount = new int[26];

        for (char c : p.toCharArray()) {
            pCount[c - 'a']++;
        }

        int matches = 0;
        int windowSize = p.length();

        // Initialize matches
        for (int i = 0; i < 26; i++) {
            if (pCount[i] == 0) matches++;
        }

        for (int i = 0; i < s.length(); i++) {
            int idx = s.charAt(i) - 'a';
            sCount[idx]++;
            if (sCount[idx] == pCount[idx]) matches++;
            else if (sCount[idx] == pCount[idx] + 1) matches--;

            if (i >= windowSize) {
                int leftIdx = s.charAt(i - windowSize) - 'a';
                sCount[leftIdx]--;
                if (sCount[leftIdx] == pCount[leftIdx]) matches++;
                else if (sCount[leftIdx] == pCount[leftIdx] - 1) matches--;
            }

            if (matches == 26) {
                result.add(i - windowSize + 1);
            }
        }

        return result;
    }
}
